import json,glob,os,collections
base='/root/.claude/projects/-home-user-fortress/fe616d40-a9c6-56d7-9da1-7168a172765d/subagents/workflows'
TPC=0.40
batch={'b9a8001b-541':14,'34063069-0ff':15,'46ebb338-7a8':16,'3d858dc3-530':17,'f345f475-9ae':18,'2408885e-820':19,'4cf8e3cb-bf5':20}
res=collections.defaultdict(lambda:collections.Counter())
per=[]
for run in sorted(os.listdir(base)):
    if run not in ('wf_4cf8e3cb-bf5','wf_2408885e-820'): continue
    for f in sorted(glob.glob(f'{base}/{run}/agent-*.jsonl')):
        lab=json.load(open(f[:-6]+'.meta.json'))['description']; ag=os.path.basename(f)[6:14]
        events=[]  # ('call',ctx,out,mid) / ('rem',chars) / ('tool',chars)
        seen=set(); tc_chars=[]  # chars of Task tool calls + results at event index
        pend={}
        for line in open(f):
            d=json.loads(line); t=d.get('type')
            if t=='assistant':
                m=d['message']; u=m.get('usage') or {}; mid=m.get('id')
                if mid not in seen:
                    seen.add(mid)
                    events.append(('call',u.get('input_tokens',0),u.get('cache_read_input_tokens',0),u.get('cache_creation_input_tokens',0),u.get('output_tokens',0)))
                for b in m['content']:
                    if b.get('type')=='tool_use' and b['name'] in('TaskCreate','TaskUpdate','TaskList','TaskGet'):
                        c=len(json.dumps(b['input'])); pend[b['id']]=c
                        events.append(('taskcall',c))
            elif t=='user' and isinstance(d['message']['content'],list):
                for b in d['message']['content']:
                    if b.get('type')=='tool_result' and b.get('tool_use_id') in pend:
                        events.append(('taskcall',len(json.dumps(b.get('content')))))
            elif t=='attachment' and d['attachment']['type']=='task_reminder':
                txt=sum(len(x.get('content','')) for x in d.get('rendered',[]) if isinstance(x,dict))
                events.append(('rem',txt))
        ncalls=sum(1 for e in events if e[0]=='call')
        # later calls count
        later=ncalls; rem_in=0; rem_rd=0; tc_in=0; tc_rd=0; k=0
        callidx=0
        for e in events:
            if e[0]=='call': callidx+=1
            elif e[0]=='rem':
                rem_in+=e[1]*TPC; rem_rd+=e[1]*TPC*(ncalls-callidx)
            elif e[0]=='taskcall':
                tc_in+=e[1]*TPC; tc_rd+=e[1]*TPC*(ncalls-callidx)
